mapper.select:
SELECT

FROM TBL_BUSINESS_RULE_MANAGE
WHERE PRIORITY_LEVEL >= #{minPriority}
AND PRIORITY_LEVEL <= #{maxPriority}
AND ORG_ID = #{orgId}
ORDER BY PRIORITY_LEVEL ASC, CREATE_TIME DESC

SELECT COUNT(*)
FROM TBL_BUSINESS_RULE_MANAGE
WHERE ORG_ID = #{orgId}

    AND RULE_TYPE = #{ruleType}


    AND BUSINESS_MODULE = #{businessModule}


    AND IS_ENABLED = #{isEnabled}

mapper.update:
UPDATE TBL_BUSINESS_RULE_MANAGE
SET IS_ENABLED = #{isEnabled},
    UPDATE_TIME = #{updateTime},
    UPDATE_USER = #{updateUser}
WHERE ID = #{id}
AND ORG_ID = (SELECT ORG_ID FROM TBL_BUSINESS_RULE_MANAGE WHERE ID = #{id})

